<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { getCandidateList, getCandidate, getWorkspace, createRecord, updateRecord, uploadAsset, downloadAsset } from '@/api/candidate'
import { getPositionList } from '@/api/position'
import { changeEmployeeRole } from '@/api/employee'
import { getHrList } from '@/api/hr'
import AppIcon from '@/components/AppIcon.vue'
import HrPicker from '@/components/HrPicker.vue'
import PersonRecordDialog from '@/components/PersonRecordDialog.vue'
import ApplicationDetailDialog from '@/components/ApplicationDetailDialog.vue'
import CommunicationRecordDialog from '@/components/CommunicationRecordDialog.vue'
import { dateTime, dateOnly, isOverdue, salary } from '@/utils/format'
function offerPay(record) { return record?.salaryMode === 'annual' ? `谈定年薪 ${record.annualSalary ?? '待补充'}K/年` : `谈定月薪 ${record?.actualSalary ?? '待补充'}K/月 · 折合年薪 ${record?.annualSalary ?? (record?.actualSalary != null ? Number((Number(record.actualSalary) * Number(record.salaryMonths || 12)).toFixed(2)) : '待补充')}K/年` }
function offerMonths(record) { return record?.salaryMode === 'annual' ? '按年薪填写' : `${record?.salaryMonths || 12}薪` }
const route = useRoute(), router = useRouter()
const data = ref({}), loading = ref(true), error = ref(''), search = ref(''), state = ref(''), busy = ref(false)
const picker = ref(false), people = ref([]), personSearch = ref(''), personLoading = ref(false), pickerError = ref('')
const transition = ref(null), transitionForm = reactive({})
const converting = ref(null), jobs = ref([]), hrs = ref([]), convertJob = ref(''), convertOwner = ref('')
const leaving = ref(null), leaveForm = reactive({ endDate: '', reason: '' })
const hiring = ref(null), hireForm = reactive({ startDate: '' })
const hireFiles = reactive({ identityFront: null, identityBack: null, graduationCertificate: null, degreeCertificate: null, educationVerification: null, departureCertificate: null })
const hireError = ref('')
const interviewDetail = ref(null)
const avatarUrls=reactive({})
const banks=['中国工商银行','中国农业银行','中国银行','中国建设银行','交通银行','中国邮政储蓄银行','招商银行','中信银行','中国光大银行','华夏银行','中国民生银行','广发银行','平安银行','兴业银行','浦发银行','浙商银行','渤海银行','北京银行','上海银行','江苏银行','南京银行','宁波银行','其他银行']
const offerEditorOpen = ref(false), offerEditorLoading = ref(false), offerPerson = ref(null), offerRecord = ref(null)
const recruitmentView = ref(localStorage.getItem('recruitmentView') || 'board')
const recruitmentStage = ref(localStorage.getItem('recruitmentStage') || '沟通中')
const communicationGrouping = ref(localStorage.getItem('communicationGrouping') || 'person')
const applicationDetail = ref(null)
const communicationOpen = ref(false), communicationPerson = ref(null), communicationApplication = ref(null)
const linkedEditorOpen = ref(false), linkedEditorPerson = ref(null), linkedEditorType = ref('events'), linkedEditorRecord = ref(null), linkedEditorMode = ref('schedule'), linkedEditorInitial = ref({})
const roleCredentials = ref(null)
const definitions = {
  recruitment: ['招聘流程', '每一次应聘独立推进，每一次选择都保留原因。', 'applications', '新增应聘流程', 'board'],
  communications: ['沟通记录', '集中查看沟通中的人才和每次联系结果，可按人才或岗位整理。', 'applications', '新增沟通记录', 'globe'],
  offers: ['Offer 发放', '每一版录用条件都与人才、岗位和应聘流程相连。', 'offers', '创建 Offer', 'briefcase'],
  onboarding: ['入职流程', '从确认 Offer 到正式入职，集中办理每一位新同事。', 'applications', '', 'check'],
  interviews: ['面试安排', '先安排面试，再记录面试结果和评价依据。', 'interviews', '安排面试', 'calendar'],
  employees: ['员工管理', '统一管理员工任职状态、HR 角色和登录账号。', 'employees', '', 'people']
}
const key = computed(() => route.path.slice(1))
const config = computed(() => definitions[key.value] || definitions.recruitment)
const type = computed(() => config.value[2])
const records = computed(() => {
  let source = [...(data.value[type.value] || [])]
  if (type.value === 'offers') {
    const latestByPerson = new Map()
    for (const record of source) {
      const previous = latestByPerson.get(record.personId)
      const currentRank = record.currentRecord ? 1 : 0, previousRank = previous?.currentRecord ? 1 : 0
      const recordTime = String(record.updatedAt || record.createdAt || ''), previousTime = String(previous?.updatedAt || previous?.createdAt || '')
      if (!previous || currentRank > previousRank || (currentRank === previousRank && recordTime > previousTime) || (currentRank === previousRank && recordTime === previousTime && Number(record.version || 0) > Number(previous.version || 0))) latestByPerson.set(record.personId, record)
    }
    source = [...latestByPerson.values()]
  }
  if (key.value === 'onboarding') {
    const latestOffers = new Map()
    for (const offer of data.value.offers || []) {
      const mapKey = String(offer.applicationId || offer.personId)
      const previous = latestOffers.get(mapKey)
      if (!previous || Boolean(offer.currentRecord) || Number(offer.version || 0) > Number(previous.version || 0)) latestOffers.set(mapKey, offer)
    }
    source = source.filter(record => ['Offer中', '待入职', '已入职'].includes(record.status)).map(record => ({ ...record, latestOffer: latestOffers.get(String(record.id)) || latestOffers.get(String(record.personId)) }))
  }
  if (key.value === 'communications') source = source.filter(record => columns[0].match.includes(record.status))
  return source.filter(r => {
  const query = search.value.trim().toLowerCase()
  const searchable = [r.personName, r.jobName, r.title, r.projectName, r.owner, r.reason, r.feedback].join(' ').toLowerCase()
  return (!query || searchable.includes(query)) && (!state.value || (state.value === '逾期' ? isOverdue(r) : state.value === '待完成' ? r.status !== '已完成' : r.status === state.value))
  })
})
const onboardingGroups = computed(() => {
  const groups = new Map()
  for (const record of records.value) {
    const groupKey = String(record.jobId || record.jobName || 'unassigned')
    if (!groups.has(groupKey)) groups.set(groupKey, { key: groupKey, jobId: record.jobId, jobName: record.jobName || '岗位待补充', company: record.company || '未设置公司', jobCode: record.jobCode || '', headcount: record.headcount || 1, hiredCount: record.hiredCount || 0, offers: [] })
    groups.get(groupKey).offers.push(record)
  }
  return [...groups.values()]
})
const offerGroups = computed(() => {
  const groups = new Map()
  for (const job of jobs.value) groups.set(String(job.id), { key: String(job.id), jobId: job.id, jobName: job.name || '未命名岗位', company: job.company || '未设置公司', jobCode: job.recruitmentCode || '', headcount: job.headcount || 1, hiredCount: job.hiredCount || 0, occupiedCount: job.occupiedCount || 0, remainingCount: job.remainingCount ?? Math.max(0, (job.headcount || 1) - (job.occupiedCount || 0)), capacityReached: Boolean(job.capacityReached), status: job.status || '招聘中', offers: [] })
  for (const record of records.value) {
    const groupKey = String(record.jobId || record.jobName || 'unassigned')
    if (!groups.has(groupKey)) groups.set(groupKey, { key: groupKey, jobId: record.jobId, jobName: record.jobName || '岗位待补充', company: record.company || '未设置公司', jobCode: record.jobCode || '', headcount: record.headcount || 1, hiredCount: record.hiredCount || 0, occupiedCount: record.occupiedCount || 0, remainingCount: record.remainingCount ?? 0, capacityReached: Boolean(record.capacityReached), status: '招聘中', offers: [] })
    groups.get(groupKey).offers.push(record)
  }
  return [...groups.values()].filter(group => group.offers.length || group.status === '招聘中')
})
const noOfferCapacity = computed(() => jobs.value.length > 0 && jobs.value.filter(job => !job.status || job.status === '招聘中').every(job => job.capacityReached || Number(job.remainingCount || 0) <= 0))
const interviewGroups = computed(() => {
  const groups = new Map()
  for (const record of records.value) {
    const groupKey = String(record.jobId || record.jobName || 'unassigned')
    if (!groups.has(groupKey)) groups.set(groupKey, { key: groupKey, company: record.company || '未设置公司', jobName: record.jobName || '岗位待补充', jobCode: record.jobCode || '', headcount: record.headcount || 1, hiredCount: record.hiredCount || 0, interviews: [] })
    groups.get(groupKey).interviews.push(record)
  }
  return [...groups.values()].map(group => ({ ...group, interviews: group.interviews.sort((a, b) => String(b.scheduledAt || b.createdAt || '').localeCompare(String(a.scheduledAt || a.createdAt || ''))) }))
})
const communicationGroups = computed(() => {
  const groups = new Map()
  for (const record of records.value) {
    const groupKey = String(record.jobId || record.jobName || 'unassigned')
    if (!groups.has(groupKey)) groups.set(groupKey, { key: groupKey, company: record.company || '未设置公司', jobName: record.jobName || '岗位待补充', jobCode: record.jobCode || '', headcount: record.headcount || 1, hiredCount: record.hiredCount || 0, records: [] })
    groups.get(groupKey).records.push(record)
  }
  return [...groups.values()]
})
const applicationDetailPosition = computed(() => jobs.value.find(job => String(job.id) === String(applicationDetail.value?.jobId)) || null)
const interviewDetailPosition = computed(() => jobs.value.find(job => String(job.id) === String(interviewDetail.value?.jobId)) || null)
const states = computed(() => [...new Set(records.value.map(r => r.status).filter(Boolean))])
const columns = [
  { title: '沟通中', match: ['已创建','初筛','沟通','沟通中','待联系','新建','人才储备'] },
  { title: '面试中', match: ['面试安排','面试中','内部决策','面试'] },
  { title: 'Offer 中', match: ['谈薪','Offer','Offer中','待入职'] },
  { title: '已入职', match: ['已入职'] }
]
const board = computed(() => columns.map(column => ({ ...column, records: records.value.filter(record => column.match.includes(record.status)) })))
const selectedRecruitmentColumn = computed(() => board.value.find(column => column.title === recruitmentStage.value) || board.value[0])
const applicationStatuses = ['沟通中','面试中','Offer中','已入职','候选人退出','公司淘汰','人才储备','长期无响应','已关闭']
const opportunityStatuses = ['新发现','待联系','已联系','有效沟通','持续培育','暂不考虑','对方拒绝','公司放弃','重新激活']
const transitionOptions = computed(() => transition.value?.type === 'opportunities' ? (transition.value?.record.status === '已转化' ? [...opportunityStatuses, '已转化'] : opportunityStatuses) : applicationStatuses)
const convertingJob = computed(() => jobs.value.find(job => String(job.id) === String(convertJob.value)))
let epoch = 0, pickEpoch = 0
async function load() {
  const id = ++epoch; loading.value = true; error.value = ''
  try { const result = await getWorkspace(); if (id === epoch) { data.value = result; loadAvatarPhotos(result) } } catch (e) { if (id === epoch) error.value = e.message } finally { if (id === epoch) loading.value = false }
}
onMounted(async () => { await Promise.all([load(), getPositionList().then(value => { jobs.value = value }), getHrList().then(value => { hrs.value = value })]) })
onBeforeUnmount(()=>Object.values(avatarUrls).forEach(url=>URL.revokeObjectURL(url)))
async function loadAvatarPhotos(workspace){const ids=[...new Set(Object.values(workspace||{}).flatMap(value=>Array.isArray(value)?value:[]).map(item=>item.personId).filter(Boolean))];await Promise.all(ids.map(async id=>{if(avatarUrls[id])return;try{const person=await getCandidate(id),photo=(person.assets||[]).find(asset=>asset.type==='证件照');if(photo)avatarUrls[id]=URL.createObjectURL(await downloadAsset(id,photo.id))}catch{}}))}
watch(() => route.path, () => { search.value = ''; state.value = ''; load() })
async function searchPeople() {
  const id = ++pickEpoch; personLoading.value = true; pickerError.value = ''
  try { const result = await getCandidateList({ search: personSearch.value, page: 1, size: 10 }); if (id === pickEpoch) people.value = result.items || [] }
  catch (e) { if (id === pickEpoch) pickerError.value = e.message } finally { if (id === pickEpoch) personLoading.value = false }
}
function openPicker() { picker.value = true; personSearch.value = ''; searchPeople() }
function setRecruitmentView(view) { recruitmentView.value = view; localStorage.setItem('recruitmentView', view) }
function setRecruitmentStage(title) { recruitmentStage.value = title; localStorage.setItem('recruitmentStage', title) }
function setCommunicationGrouping(value) { communicationGrouping.value = value; localStorage.setItem('communicationGrouping', value) }
async function choosePerson(person) {
  picker.value = false
  if (key.value !== 'communications') { router.push({ path: '/person/' + person.id, query: { action: type.value } }); return }
  try {
    const profile = await getCandidate(person.id)
    const application = (profile.applications || []).find(item => columns[0].match.includes(item.status)) || profile.applications?.[0]
    if (!application) { ElMessage.warning('这个人才还没有应聘流程，请先在人才档案中建立应聘记录'); return }
    openCommunicationEditor(profile, application)
  } catch (cause) { ElMessage.error(cause.message || '人才资料读取失败') }
}
function openApplicationDetail(record) { applicationDetail.value = record }
function openTransitionFromDetail(record) { applicationDetail.value = null; openTransition(record, 'applications') }
async function openLinkedEditor(profileOrApplication, recordType, initial = {}, record = null, mode = 'schedule') {
  try {
    const profile = profileOrApplication.applications ? profileOrApplication : await getCandidate(profileOrApplication.personId)
    linkedEditorPerson.value = profile
    linkedEditorType.value = recordType
    linkedEditorRecord.value = record
    linkedEditorMode.value = mode
    linkedEditorInitial.value = initial
    linkedEditorOpen.value = true
  } catch (cause) { ElMessage.error(cause.message || '人才资料读取失败') }
}
async function openInterviewEditor(record, mode) {
  interviewDetail.value = null
  await openLinkedEditor(record, 'interviews', { applicationId: record.applicationId }, record, mode)
}
async function recordCommunication(record) {
  applicationDetail.value = null
  try { openCommunicationEditor(await getCandidate(record.personId), record) }
  catch (cause) { ElMessage.error(cause.message || '人才资料读取失败') }
}
function openCommunicationEditor(profile, application) { communicationPerson.value = profile; communicationApplication.value = application; communicationOpen.value = true }
async function communicationSaved() { communicationOpen.value = false; await load() }
async function openApplicationNext(record, requestedAction = '') {
  const action = requestedAction || nextAction(record)
  applicationDetail.value = null
  if (action === 'interview') { await openLinkedEditor(record, 'interviews', { applicationId: record.id, owner: record.owner || '' }); return }
  if (action === 'interview-result') {
    const latest = (data.value.interviews || []).filter(item => String(item.applicationId) === String(record.id)).sort((a, b) => String(b.scheduledAt || b.createdAt || '').localeCompare(String(a.scheduledAt || a.createdAt || '')))[0]
    if (latest) await openLinkedEditor(record, 'interviews', { applicationId: record.id }, latest, 'evaluation')
    else await openLinkedEditor(record, 'interviews', { applicationId: record.id, owner: record.owner || '' })
    return
  }
  if (action === 'offer') { await openLatestOfferForApplication(record); return }
  if (action === 'hire') openHire(record)
}
async function openLatestOfferForApplication(record) {
  offerEditorLoading.value = true
  try { offerPerson.value = await getCandidate(record.personId); offerRecord.value = null; offerEditorOpen.value = true }
  catch (cause) { ElMessage.error(cause.message || '人才资料读取失败') }
  finally { offerEditorLoading.value = false }
}
async function linkedRecordSaved() { const applicationId = applicationDetail.value?.id; linkedEditorOpen.value = false; await load(); if (applicationId) applicationDetail.value = (data.value.applications || []).find(item => String(item.id) === String(applicationId)) || applicationDetail.value }
async function editInterviewFromDetail(record, mode) { if (!applicationDetail.value) return; await openLinkedEditor(applicationDetail.value, 'interviews', { applicationId: applicationDetail.value.id, owner: applicationDetail.value.owner || '' }, record, mode) }
async function editOfferFromDetail(record) { await openLatestOfferForApplication(record) }
function openInterviewDetail(record) { interviewDetail.value = record }
async function openLatestOffer(record) {
  if (type.value !== 'offers' || offerEditorLoading.value) return
  offerEditorLoading.value = true
  try {
    const profile = await getCandidate(record.personId)
    offerPerson.value = profile
    offerRecord.value = (profile.offers || []).find(item => String(item.id) === String(record.id)) || record
    offerEditorOpen.value = true
  } catch (cause) { ElMessage.error(cause.message || 'Offer 读取失败') }
  finally { offerEditorLoading.value = false }
}
async function offerSaved() { offerEditorOpen.value = false; await load() }
async function regularize(record) {
  if (busy.value) return; busy.value = true
  try { await updateRecord(record.personId, 'employments', record.employmentItemId, { ...record, id: record.employmentItemId, status: '已转正' }); ElMessage.success('已办理转正'); await load() }
  catch (e) { ElMessage.error(e.message) } finally { busy.value = false }
}
function openLeave(record) { leaving.value = record; leaveForm.endDate = new Date().toISOString().slice(0, 10); leaveForm.reason = '' }
async function openHire(record) {
  if (busy.value) return
  busy.value = true; hireError.value = ''
  try {
    const profile = await getCandidate(record.personId)
    const today = new Date().toISOString().slice(0, 10), planned = String(record.latestOffer?.expectedStartDate || '').slice(0, 10)
    Object.keys(hireForm).forEach(key => delete hireForm[key]); Object.keys(hireFiles).forEach(key => { hireFiles[key] = null })
    Object.assign(hireForm, { employmentCategory: '全职', hireChannel: '社招', preEmploymentStatus: '', startDate: planned && planned >= today ? planned : today, employeeName: profile.name || record.personName || '', employeePhone: profile.phone || '', employeeEmail: profile.email || '', identityNumber: '', bankName: '', bankAccount: '', address: '', householdRegistration: '', emergencyContact: '', emergencyPhone: '' })
    hiring.value = record
  } catch (e) { ElMessage.error(e.message || '人才资料读取失败') }
  finally { busy.value = false }
}
function onboardingStep(record) { return record.status === '已入职' ? 3 : record.status === '待入职' ? 2 : 1 }
function disablePastDay(value) { const today = new Date(); today.setHours(0, 0, 0, 0); return value < today }
function nextAction(record) { if (columns[0].match.includes(record.status)) return 'interview'; if (columns[1].match.includes(record.status)) { const related = (data.value.interviews || []).filter(item => String(item.applicationId) === String(record.id)); return related.some(item => item.status === '已完成' && item.result && !['待评价', '不推荐'].includes(item.result)) ? 'offer' : (related.length ? 'interview-result' : 'interview') } if (columns[2].match.includes(record.status)) return 'hire'; return '' }
function nextRoute(record) { const action = nextAction(record) === 'interview' ? 'interviews' : 'offers'; return { path: '/person/' + record.personId, query: { action, applicationId: record.id } } }
function chooseHireFile(key, event) { hireFiles[key] = event.target.files?.[0] || null }
function hireFileRequired(key) { if (['identityFront','identityBack'].includes(key)) return true; if (hireForm.employmentCategory !== '全职') return false; if (hireForm.hireChannel === '校招') return ['graduationCertificate','degreeCertificate','educationVerification'].includes(key); return hireForm.hireChannel === '社招' && hireForm.preEmploymentStatus === '离职' && key === 'departureCertificate' }
function validateHire() {
  const required = [['employeeName','姓名'],['employeePhone','电话'],['employeeEmail','邮箱'],['identityNumber','身份证号'],['startDate','到岗日期'],['bankName','开户银行'],['bankAccount','银行卡号'],['address','现住址'],['householdRegistration','户籍地址'],['emergencyContact','紧急联系人'],['emergencyPhone','紧急联系电话']]
  for (const [key,label] of required) if (!String(hireForm[key] || '').trim()) return `请填写${label}`
  if (!/^(?:\+?86)?1[3-9]\d{9}$/.test(String(hireForm.employeePhone).replace(/[\s()-]/g,''))) return '请填写正确的手机号'
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(hireForm.employeeEmail)) return '请填写正确的邮箱'
  if (!/^(?:\+?86)?1[3-9]\d{9}$/.test(String(hireForm.emergencyPhone).replace(/[\s()-]/g,''))) return '请填写正确的紧急联系电话'
  if (!/^[1-9]\d{5}(?:19|20)\d{2}(?:0[1-9]|1[0-2])(?:0[1-9]|[12]\d|3[01])\d{3}[0-9Xx]$/.test(hireForm.identityNumber)) return '请填写正确的 18 位身份证号'
  if (!/^\d{12,25}$/.test(String(hireForm.bankAccount).replace(/\s/g,''))) return '请填写正确的银行卡号'
  if (hireForm.employmentCategory === '全职' && !hireForm.hireChannel) return '请选择校招或社招'
  if (hireForm.employmentCategory === '全职' && hireForm.hireChannel === '社招' && !hireForm.preEmploymentStatus) return '请选择社招人才当前是在职还是离职'
  const missingFiles = Object.keys(hireFiles).filter(key => hireFileRequired(key) && !hireFiles[key])
  if (missingFiles.length) return '请上传所有标记为必填的入职材料'
  return ''
}
async function saveHire() {
  if (!hiring.value || busy.value) return
  hireError.value = validateHire(); if (hireError.value) { ElMessage.error(hireError.value); return }
  busy.value = true
  try {
    const labels = { identityFront: '入职-身份证正面', identityBack: '入职-身份证反面', graduationCertificate: '入职-毕业证', degreeCertificate: '入职-学位证', educationVerification: '入职-学籍验证报告', departureCertificate: '入职-离职证明' }
    const documents = {}
    const uploaded=await Promise.all(Object.entries(hireFiles).filter(([,file])=>file).map(async([key,file])=>[key,await uploadAsset(hiring.value.personId,file,labels[key])]))
    for(const [key,asset] of uploaded){documents[key+'AssetId']=asset.id;documents[key+'FileName']=asset.name}
    await updateRecord(hiring.value.personId, 'applications', hiring.value.id, { ...hiring.value, ...hireForm, ...documents, bankAccount: String(hireForm.bankAccount).replace(/\s/g,''), onboardedAt: new Date().toISOString(), status: '已入职' })
    hiring.value = null; ElMessage.success('入职资料已归档，员工记录已自动建立'); await load()
  } catch (e) { hireError.value = e.response?.data?.message || e.message || '办理入职失败'; ElMessage.error(hireError.value) }
  finally { busy.value = false }
}
async function saveLeave() {
  if (!leaveForm.endDate || !leaveForm.reason.trim()) { ElMessage.warning('请填写离职日期和离职原因'); return }
  busy.value = true
  try { await updateRecord(leaving.value.personId, 'employments', leaving.value.employmentItemId, { ...leaving.value, id: leaving.value.employmentItemId, status: '已离职', endDate: leaveForm.endDate, reason: leaveForm.reason }); leaving.value = null; ElMessage.success('离职已办理并保留记录'); await load() }
  catch (e) { ElMessage.error(e.message) } finally { busy.value = false }
}
async function toggleEmployeeRole(record) {
  const employeeId = record.employeeId || record.id
  if (!employeeId || busy.value) return
  busy.value = true
  try { const result = await changeEmployeeRole(employeeId, (record.employeeRole || record.role) === 'HR' ? 'EMPLOYEE' : 'HR'); roleCredentials.value = result.accountCreated ? result : null; ElMessage.success(result.accountCreated ? '已设为 HR，并生成登录账号' : '员工角色已更新'); await load() }
  catch (cause) { ElMessage.error(cause.response?.data?.message || cause.message || '角色更新失败') }
  finally { busy.value = false }
}
function defaultHr() { return (hrs.value.find(hr => hr.current) || hrs.value[0])?.name || '' }
function openTransition(record, recordType) { transition.value = { record, type: recordType }; Object.keys(transitionForm).forEach(key => delete transitionForm[key]); if (recordType === 'opportunities') Object.assign(transitionForm, { title: record.title || '', jobId: record.jobId || '', startedAt: String(record.startedAt || '').slice(0, 10), owner: hrs.value.some(hr => hr.name === record.owner) ? record.owner : defaultHr(), status: record.status || '新发现', companyIntent: record.companyIntent || '未判断', talentIntent: record.talentIntent || '未知', summary: record.summary || '', reason: record.reason || '', nextStep: record.nextStep || '', nextContactAt: String(record.nextContactAt || '').slice(0, 16) }); else Object.assign(transitionForm, { status: record.status, reason: record.reason || '' }) }
async function saveTransition() {
  if (busy.value) return
  if (transition.value?.type === 'opportunities' && (!transitionForm.title?.trim() || !transitionForm.owner)) { ElMessage.warning('请填写寻访标题并选择 HR'); return }
  if (['暂不考虑','对方拒绝','公司放弃','候选人退出','公司淘汰','岗位取消','长期无响应','已关闭'].includes(transitionForm.status) && !transitionForm.reason?.trim()) { ElMessage.warning('关闭或暂停时请填写具体原因'); return }
  busy.value = true
  try { const { record, type: recordType } = transition.value; await updateRecord(record.personId, recordType, record.id, { ...record, ...transitionForm }); transition.value = null; ElMessage.success('已更新并保留历史'); await load() }
  catch (e) { ElMessage.error(e.message) } finally { busy.value = false }
}
async function openConversion(record) {
  try { converting.value = record; convertJob.value = record.jobId || ''; convertOwner.value = hrs.value.some(hr => hr.name === record.owner) ? record.owner : defaultHr() } catch (e) { ElMessage.error(e.message) }
}
async function convert() {
  if (busy.value) return
  if (!convertJob.value) { ElMessage.warning('请先选择本次应聘岗位'); return }
  if (!convertOwner.value) { ElMessage.warning('请选择本次 HR'); return }
  busy.value = true
  try {
    await createRecord(converting.value.personId, 'applications', { jobId: Number(convertJob.value), opportunityId: converting.value.id, status: '已创建', owner: convertOwner.value, startedAt: new Date().toISOString(), companyIntent: converting.value.companyIntent, talentIntent: converting.value.talentIntent })
    converting.value = null; ElMessage.success('已为这位人才创建应聘经历，原寻访记录继续保留'); await load()
  } catch (e) { ElMessage.error(e.message) } finally { busy.value = false }
}
function label(record) { return record.title || record.projectName || record.jobName || record.job || record.round || '人才记录' }
function timing(record) { return record.scheduledAt || record.dueAt || record.startedAt || record.startDate || record.createdAt }
</script>
<template>
  <div class="page-heading"><div><div class="eyebrow">CONNECTED THROUGH EVERY CHAPTER</div><h1>{{ config[0] }}</h1><p>{{ config[1] }}</p></div><div class="page-heading-actions"><div v-if="key === 'recruitment'" class="view-switch" role="group" aria-label="招聘流程视图"><button :class="{ active: recruitmentView === 'board' }" @click="setRecruitmentView('board')">看板</button><button :class="{ active: recruitmentView === 'table' }" @click="setRecruitmentView('table')">表格</button></div><div v-if="key === 'communications'" class="view-switch" role="group" aria-label="沟通记录分组"><button :class="{ active: communicationGrouping === 'person' }" @click="setCommunicationGrouping('person')">按人才</button><button :class="{ active: communicationGrouping === 'position' }" @click="setCommunicationGrouping('position')">按岗位</button></div><button v-if="config[3]" class="btn btn-primary" :disabled="key === 'offers' && noOfferCapacity" :title="key === 'offers' && noOfferCapacity ? '所有招聘中岗位的名额都已占满' : ''" @click="openPicker"><AppIcon name="plus" :size="16" />{{ type === 'offers' ? (noOfferCapacity ? '岗位名额已满' : '创建 Offer') : config[3] }}</button><button v-else class="btn" @click="load">刷新数据</button></div></div>
  <div v-if="error" class="error-state" role="alert">{{ error }} <button class="btn btn-small" @click="load">重试</button></div><div v-else-if="loading" class="surface loading-state"><span class="spinner"></span>正在读取数据…</div>
  <template v-else>
    <div class="workspace-toolbar"><label class="table-search"><AppIcon name="search" :size="15" /><input v-model="search" :aria-label="'搜索' + config[0]" placeholder="搜索人才、岗位、HR…" /></label><select v-model="state" aria-label="筛选状态"><option value="">全部状态</option><option v-for="option in states" :key="option">{{ option }}</option></select><span class="muted" style="align-self:center">{{ records.length }} {{ type === 'offers' ? '位人才' : '条记录' }}</span></div>
    <div v-if="key === 'recruitment' && recruitmentView === 'board'" class="board-grid"><section v-for="column in board" :key="column.title" class="board-column"><h2 class="board-column-title">{{ column.title }}<span>{{ column.records.length }}</span></h2><article v-for="record in column.records" :key="record.id" class="board-card application-card" role="button" tabindex="0" @click="openApplicationDetail(record)" @keydown.enter="openApplicationDetail(record)"><h3>{{ record.personName }}</h3><p>{{ record.company || '未设置公司' }}：{{ record.jobName || '岗位待补充' }}：{{ record.jobCode || String(record.jobId || '').padStart(3, '0') }}</p><span class="badge" :class="record.status === '已入职' ? 'green' : ''">{{ record.status }}</span><small>岗位已招 {{ record.hiredCount || 0 }} / {{ record.headcount || 1 }} 人</small><small>公司意愿：{{ record.companyIntent || '未判断' }} · 人才意愿：{{ record.talentIntent || '未知' }}</small><small>{{ dateOnly(record.startedAt || record.createdAt) }} · HR {{ record.owner || '待分配' }}</small><p v-if="record.reason" style="margin-top:12px">{{ record.reason }}</p><div class="board-actions"><button v-if="nextAction(record)" class="btn btn-small btn-primary" @click.stop="openApplicationNext(record)">{{ nextAction(record) === 'interview' ? '约面试' : nextAction(record) === 'interview-result' ? '填写结果' : nextAction(record) === 'offer' ? '发 Offer' : '办理入职' }}</button><button class="text-link" @click.stop="openTransition(record, 'applications')">记录结果</button></div></article><div v-if="!column.records.length" class="compact-empty">暂无流程</div></section></div>
    <div v-else-if="key === 'recruitment'" class="recruitment-table-view"><nav class="recruitment-flow-tabs" aria-label="选择招聘流程"><button v-for="column in board" :key="column.title" type="button" :class="{active:selectedRecruitmentColumn.title===column.title}" @click="setRecruitmentStage(column.title)"><span>{{column.title}}</span><b>{{column.records.length}}</b></button></nav><section class="surface recruitment-stage"><header><div><small>当前流程</small><h2>{{ selectedRecruitmentColumn.title }}</h2></div><span>{{ selectedRecruitmentColumn.records.length }} 人</span></header><div class="recruitment-table-wrap"><table><thead><tr><th>人才</th><th>公司 / 岗位</th><th>当前状态</th><th>双方意愿</th><th>HR</th><th>进入流程</th><th>操作</th></tr></thead><tbody><tr v-for="record in selectedRecruitmentColumn.records" :key="record.id" class="application-row" tabindex="0" @click="openApplicationDetail(record)" @keydown.enter="openApplicationDetail(record)"><td><b>{{ record.personName }}</b></td><td>{{ record.company || '未设置公司' }} · {{ record.jobName || '岗位待补充' }}<small>已招 {{ record.hiredCount || 0 }} / {{ record.headcount || 1 }} 人</small></td><td><span class="badge" :class="record.status === '已入职' ? 'green' : ''">{{ record.status }}</span></td><td>公司 {{ record.companyIntent || '未判断' }} · 人才 {{ record.talentIntent || '未知' }}</td><td>{{ record.owner || '待分配' }}</td><td>{{ dateOnly(record.startedAt || record.createdAt) }}</td><td><div class="table-actions"><button v-if="nextAction(record)" class="text-link" @click.stop="openApplicationNext(record)">{{ nextAction(record) === 'interview' ? '约面试' : nextAction(record) === 'interview-result' ? '填写结果' : nextAction(record) === 'offer' ? '发 Offer' : '办理入职' }}</button><button class="text-link" @click.stop="openTransition(record, 'applications')">记录结果</button></div></td></tr><tr v-if="!selectedRecruitmentColumn.records.length"><td colspan="7" class="table-empty">当前流程暂无人才</td></tr></tbody></table></div></section></div>
    <div v-else-if="key === 'communications' && communicationGrouping === 'person'" class="surface communication-table-panel"><div class="communication-table-wrap"><table class="communication-table"><thead><tr><th>人才</th><th>应聘岗位</th><th>状态</th><th>双方意愿</th><th>负责 HR</th><th>下一次沟通</th><th></th></tr></thead><tbody><tr v-for="record in records" :key="record.id" tabindex="0" @click="openApplicationDetail(record)" @keydown.enter="openApplicationDetail(record)"><td><div class="communication-person"><span class="person-avatar large"><img v-if="avatarUrls[record.personId]" :src="avatarUrls[record.personId]" :alt="record.personName+'的证件照'" /><template v-else>{{record.personName?.slice(0,1)||'人'}}</template></span><div><strong>{{record.personName}}</strong><small>进入流程 {{dateOnly(record.startedAt||record.createdAt)}}</small></div></div></td><td><strong class="communication-job">{{record.jobName||'岗位待补充'}}</strong><small>{{record.company||'未设置公司'}} · 已招 {{ record.hiredCount || 0 }} / {{ record.headcount || 1 }} 人</small></td><td><span class="badge">{{record.status}}</span></td><td><span class="intent-line">公司 {{record.companyIntent||'未判断'}}</span><span class="intent-line">人才 {{record.talentIntent||'未知'}}</span></td><td>{{record.owner||'待分配'}}</td><td><strong>{{record.nextStep||record.reason||'待安排'}}</strong><small>{{record.nextContactAt?dateTime(record.nextContactAt):'尚未设置时间'}}</small></td><td><b class="communication-entry">查看记录 →</b></td></tr></tbody></table></div></div>
    <div v-else-if="key === 'communications'" class="communication-position-groups"><section v-for="group in communicationGroups" :key="group.key" class="surface communication-position"><header><div><small>岗位</small><h2>{{ group.company }} · {{ group.jobName }}</h2><p>岗位编号 {{ group.jobCode || '待补充' }} · 已招 {{ group.hiredCount }} / {{ group.headcount }} 人</p></div><span>{{ group.records.length }} 位沟通中人才</span></header><div class="communication-position-list"><article v-for="record in group.records" :key="record.id" class="communication-position-card" role="button" tabindex="0" @click="openApplicationDetail(record)" @keydown.enter="openApplicationDetail(record)"><div><h3>{{ record.personName }}</h3><small>HR {{ record.owner || '待分配' }} · {{ dateOnly(record.startedAt || record.createdAt) }}</small></div><span class="badge">{{ record.status }}</span><p>公司 {{ record.companyIntent || '未判断' }} · 人才 {{ record.talentIntent || '未知' }}</p><b class="communication-entry">查看沟通记录 →</b></article></div></section></div>
    <div v-else-if="key === 'offers' && offerGroups.length" class="offer-position-groups"><section v-for="group in offerGroups" :key="group.key" class="surface offer-position"><header><div><small>招聘岗位</small><h2>{{ group.company }} · {{ group.jobName }}</h2><p>岗位编号 {{ group.jobCode || group.jobId || '待补充' }}</p></div><div class="position-capacity" :class="{ full: group.capacityReached }"><strong>{{ group.hiredCount }} / {{ group.headcount }}</strong><span>已招 / 名额</span><small>{{ group.capacityReached ? '名额已满' : `还可发放 ${group.remainingCount} 份` }}</small></div></header><div v-if="group.offers.length" class="offer-position-list"><article v-for="record in group.offers" :key="record.id" class="offer-person-card" role="button" tabindex="0" @click="openLatestOffer(record)" @keydown.enter="openLatestOffer(record)"><div class="offer-person-head"><span class="interview-avatar"><img v-if="avatarUrls[record.personId]" :src="avatarUrls[record.personId]" :alt="record.personName+'的证件照'" /><template v-else>{{ record.personName?.slice(0,1) || '人' }}</template></span><div><h3>{{ record.personName }}</h3><small>第 {{ record.version || 1 }} 版 · HR {{ record.owner || '待安排' }}</small></div><span class="badge" :class="record.status === '已完成' ? 'green' : ''">{{ record.responseStatus || record.status || '草稿' }}</span></div><strong class="offer-person-pay">{{ offerPay(record) }}</strong><p>预计入职 {{ dateOnly(record.expectedStartDate) }} · 有效期至 {{ dateOnly(record.expiresAt) }}</p><footer><span>{{ record.status === '已完成' ? '已锁定发送版本' : '可继续修改' }}</span><b>查看 Offer →</b></footer></article></div><div v-else class="offer-position-empty"><b>这个岗位还没有 Offer</b><span>{{ group.capacityReached ? '岗位名额已经占满。' : '面试通过后，可为候选人创建 Offer。' }}</span></div></section></div>
    <div v-else-if="key === 'onboarding' && records.length" class="onboarding-groups"><section v-for="group in onboardingGroups" :key="group.key" class="surface onboarding-position"><header><div><small>岗位</small><h2>{{ group.company }} · {{ group.jobName }}</h2><p>岗位编号 {{ group.jobCode || '待补充' }} · 已招 {{ group.hiredCount }} / {{ group.headcount }} 人</p></div><span>{{ group.offers.length }} 份 Offer</span></header><div class="onboarding-list"><article v-for="record in group.offers" :key="record.id" class="onboarding-card"><div class="onboarding-person"><span class="onboarding-avatar"><img v-if="avatarUrls[record.personId]" :src="avatarUrls[record.personId]" :alt="record.personName+'的证件照'" /><template v-else>{{ record.personName?.slice(0, 1) || '人' }}</template></span><div><router-link :to="{ path: '/person/' + record.personId, query: { tab: 'offers' } }"><h3>{{ record.personName }}</h3></router-link><small>HR {{ record.owner || '待安排' }}</small></div><span class="badge" :class="record.status === '已入职' ? 'green' : ''">{{ record.status }}</span></div><div class="onboarding-progress"><span :class="{ done: onboardingStep(record) >= 1 }"><i>1</i><b>Offer 已确认</b></span><span :class="{ done: onboardingStep(record) >= 2 }"><i>2</i><b>等待入职</b></span><span :class="{ done: onboardingStep(record) >= 3 }"><i>3</i><b>正式入职</b></span></div><div class="onboarding-facts"><span><small>计划入职</small><b>{{ dateOnly(record.latestOffer?.expectedStartDate) }}</b></span><span><small>Offer 有效期</small><b>{{ dateOnly(record.latestOffer?.expiresAt) }}</b></span><span><small>谈定薪资</small><b>{{ record.latestOffer ? offerPay(record.latestOffer).replace('谈定', '') : '待补充' }}</b></span></div><div class="onboarding-actions"><router-link class="btn btn-small btn-plain" :to="{ path: '/person/' + record.personId, query: { tab: 'offers' } }">查看档案</router-link><button v-if="record.status !== '已入职'" class="btn btn-small btn-primary" :disabled="busy" @click="openHire(record)">办理入职</button><span v-else class="onboarding-complete">已建立员工记录</span></div></article></div></section></div>
    <div v-else-if="key === 'interviews' && records.length" class="interview-groups"><section v-for="group in interviewGroups" :key="group.key" class="surface interview-position"><header><div><small>应聘岗位</small><h2>{{ group.jobName }}</h2><p>{{ group.company }}<template v-if="group.jobCode"> · 岗位编号 {{ group.jobCode }}</template> · 已招 {{ group.hiredCount }} / {{ group.headcount }} 人</p></div><span>{{ group.interviews.length }} 位面试者</span></header><div class="interview-candidates"><button v-for="record in group.interviews" :key="record.id" type="button" class="interview-candidate" :class="{ completed: record.status === '已完成' }" @click="openInterviewDetail(record)"><div class="interview-card-top"><span class="interview-avatar"><img v-if="avatarUrls[record.personId]" :src="avatarUrls[record.personId]" :alt="record.personName+'的证件照'" /><template v-else>{{ record.personName?.slice(0, 1) || '人' }}</template></span><span><b>{{ record.personName }}</b><small>{{ dateTime(record.scheduledAt || record.createdAt) }}</small></span><i class="badge" :class="record.status === '已完成' ? 'green' : ''">{{ record.status || '待面试' }}</i></div><div class="interview-summary"><span><small>轮次</small><b>{{ record.round || '待补充' }}</b></span><span><small>方式</small><b>{{ record.method || '待补充' }}</b></span><span><small>面试官</small><b>{{ record.owner || '待安排' }}</b></span></div><div class="interview-result"><small>{{ record.status === '已完成' ? '面试结论' : '当前进度' }}</small><strong>{{ record.status === '已完成' ? (record.result || '结果待补充') : '等待面试完成' }}</strong><p>{{ record.status === '已完成' ? (record.feedback || '面试已完成，评价待补充。') : '面试完成后在这里记录评分、结论和评价。' }}</p></div><footer><span v-if="record.status === '已完成' && record.score != null">{{ record.score }} 分</span><b>查看详情 <i>→</i></b></footer></button></div></section></div>
    <div v-else-if="!records.length" class="surface empty-state"><AppIcon :name="config[4]" :size="36" /><h3>还没有{{ config[0] }}记录</h3><p>{{ key === 'onboarding' ? 'Offer 确认后，人才会自动进入这里等待办理入职。' : '从一位已建档人才开始，记录下一段故事。' }}</p><button v-if="config[3]" class="btn btn-primary" @click="openPicker">{{ type === 'offers' ? '创建 Offer' : config[3] }}</button></div>
    <div v-else class="workspace-grid"><article v-for="record in records" :key="record.id" class="surface record-card" :class="{ 'record-card-clickable': type === 'offers' }" :role="type === 'offers' ? 'button' : undefined" :tabindex="type === 'offers' ? 0 : undefined" @click="openLatestOffer(record)" @keydown.enter="openLatestOffer(record)"><div class="record-topline"><router-link v-if="record.personId" :to="{ path: '/person/' + record.personId, query: type === 'offers' ? { tab: 'offers' } : {} }" class="text-link" @click.stop>{{ record.personName }}</router-link><b v-else>{{ record.personName }}</b><span class="badge" :class="record.status === '已完成' || record.status === '已入职' || record.status === '在职' || record.status === '已转正' || record.status === '已接受' ? 'green' : isOverdue(record) ? 'rose' : ''">{{ record.status || '已记录' }}</span></div><h3>{{ label(record) }}</h3>
      <template v-if="key === 'interviews'"><p>{{ record.round || '面试' }} · {{ record.method || '方式待补充' }} · HR {{ record.owner || '待安排' }}</p><p v-if="record.feedback">{{ record.feedback }}</p><span v-if="record.score != null" class="badge">面评 {{ record.score }} 分</span><span v-if="record.result" class="badge gray" style="margin-left:6px">{{ record.result }}</span></template>
      <template v-else-if="type === 'offers'"><section class="offer-card-position"><small>应聘岗位</small><strong>{{ record.jobName || '岗位待补充' }}</strong><span>{{ record.company || '公司待补充' }}<template v-if="record.jobCode"> · {{ record.jobCode }}</template></span></section><p class="offer-card-pay">{{ offerPay(record) }}</p><p>岗位预算 {{ salary(record) }} · {{ offerMonths(record) }} · {{ record.probationMonths ? record.probationMonths + '个月试用期' : '无试用期' }}<br>预计入职 {{ dateOnly(record.expectedStartDate) }} · 有效期至 {{ dateOnly(record.expiresAt) }}</p></template>
      <template v-else-if="key === 'opportunities'"><p>公司：{{ record.companyIntent || '未判断' }} · 人才：{{ record.talentIntent || '未知' }}</p><p>{{ record.nextStep || record.summary || '下一步待安排' }}</p></template>
      <template v-else-if="key === 'collaborations'"><p>{{ record.role || '合作角色待补充' }} · {{ dateOnly(record.startDate) }} — {{ dateOnly(record.endDate) }}</p><p>{{ record.feedback || '合作评价待补充' }}</p></template>
      <template v-else-if="key === 'employees'"><p>{{ dateOnly(record.startDate) }} — {{ record.endDate ? dateOnly(record.endDate) : '至今' }}</p><p>{{ record.reason || '持续记录这段任职中的成长与变化。' }}</p><div class="employee-account-line"><span>{{ record.employeeRole === 'HR' ? 'HR' : '普通员工' }}</span><small>{{ record.username ? `登录账号：${record.username}` : '无登录账号' }}</small></div></template>
      <p v-if="record.reason && key !== 'employees'">原因：{{ record.reason }}</p><div class="record-meta"><span>{{ dateTime(timing(record)) }}</span><span>{{ record.owner || record.actor || '已记录' }}</span></div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:19px"><template v-if="key === 'opportunities'"><button class="btn btn-small" @click.stop="openTransition(record, 'opportunities')">编辑寻访</button><button v-if="record.status !== '已转化'" class="btn btn-small btn-primary" @click.stop="openConversion(record)">为人才创建应聘经历</button></template><template v-if="key === 'employees' && record.status !== '已离职'"><button v-if="record.employmentItemId && record.status === '试用期'" class="btn btn-small btn-primary" :disabled="busy" @click.stop="regularize(record)">办理转正</button><button v-if="record.employmentItemId" class="btn btn-small" :disabled="busy" @click.stop="openLeave(record)">办理离职</button><button class="btn btn-small" :disabled="busy || record.currentEmployee" @click.stop="toggleEmployeeRole(record)">{{ record.employeeRole === 'HR' ? '设为普通员工' : '设为 HR' }}</button></template><button v-if="type === 'offers' && record.status !== '已完成'" class="btn btn-small btn-primary" :disabled="offerEditorLoading" @click.stop="openLatestOffer(record)">查看、修改与预览</button><router-link v-else-if="type !== 'offers' && record.personId" class="btn btn-small btn-plain" :to="{ path: '/person/' + record.personId, query: { tab: type } }" @click.stop>查看完整档案 →</router-link></div>
    </article></div>
  </template>
  <el-dialog v-model="picker" title="选择一位人才" width="560px"><p class="muted">每条业务记录都关联到人才的永久档案。</p><form class="workspace-toolbar" @submit.prevent="searchPeople"><input v-model="personSearch" placeholder="搜索姓名或联系方式" aria-label="查找关联人才" style="flex:1" /><button class="btn" :disabled="personLoading">搜索</button></form><p v-if="pickerError" class="error-state">{{ pickerError }}</p><div v-else-if="personLoading" class="loading-state">正在查找…</div><div v-else><button v-for="person in people" :key="person.id" class="picker-person" @click="choosePerson(person)"><span><b>{{ person.name }}</b><small>{{ person.job || '暂未关联岗位' }} · {{ person.source || '来源待补充' }}</small></span><AppIcon name="arrow" :size="16" /></button><p v-if="!people.length" class="empty-state">未找到人才。请先在人才库建立档案。</p></div><div class="dialog-actions"><button class="btn" @click="picker = false">取消</button><router-link class="btn btn-primary" to="/talents" @click="picker = false">前往人才库</router-link></div></el-dialog>
  <el-dialog :model-value="!!transition" @update:model-value="value => { if (!value && !busy) transition = null }" :title="transition?.type === 'opportunities' ? '编辑主动寻访' : '更新应聘状态'" width="620px"><form @submit.prevent="saveTransition"><p class="muted">{{ transition?.record.personName }} · 当前 {{ transition?.record.status }}</p><template v-if="transition?.type === 'opportunities'"><div class="edit-grid"><label class="field">寻访标题<input v-model="transitionForm.title" maxlength="240" required /></label><label class="field">关联岗位<select v-model="transitionForm.jobId"><option value="">暂不关联岗位</option><option v-for="job in jobs" :key="job.id" :value="job.id">{{ job.name }} · 已招 {{ job.hiredCount || 0 }}/{{ job.headcount || 1 }} · V{{ job.version }}</option></select></label><label class="field">首次接触日期<el-date-picker v-model="transitionForm.startedAt" type="date" value-format="YYYY-MM-DD" format="YYYY/MM/DD" style="width:100%" /></label><label class="field">HR<HrPicker v-model="transitionForm.owner" :employees="hrs" placeholder="输入姓名模糊搜索 HR" /></label><label class="field">公司意愿<select v-model="transitionForm.companyIntent"><option v-for="option in ['未判断','低','一般','较高','很高','放弃']" :key="option">{{ option }}</option></select></label><label class="field">人才意愿<select v-model="transitionForm.talentIntent"><option v-for="option in ['未知','明确拒绝','暂不考虑','可以了解','有兴趣','积极','强烈']" :key="option">{{ option }}</option></select></label></div><label class="field spaced">沟通摘要<textarea v-model="transitionForm.summary" rows="3" maxlength="4000"></textarea></label><label class="field spaced">下一步<input v-model="transitionForm.nextStep" maxlength="500" /></label><label class="field spaced">下次跟进时间<el-date-picker v-model="transitionForm.nextContactAt" type="datetime" value-format="YYYY-MM-DDTHH:mm" format="YYYY/MM/DD HH:mm" style="width:100%" /></label></template><label class="field spaced">更新状态<select v-model="transitionForm.status"><option v-for="option in transitionOptions" :key="option">{{ option }}</option></select></label><label class="field spaced">原因 / 结果<textarea v-model="transitionForm.reason" rows="3" placeholder="关闭、拒绝或暂停时必填；正常推进可留空。" maxlength="4000"></textarea></label><div class="dialog-actions"><button type="button" class="btn" :disabled="busy" @click="transition = null">取消</button><button class="btn btn-primary" :disabled="busy">{{ busy ? '保存中…' : '保存状态' }}</button></div></form></el-dialog>
  <el-dialog :model-value="!!converting" @update:model-value="value => { if (!value && !busy) converting = null }" title="为人才创建应聘经历" width="510px"><p class="muted">这是把“正在主动接触”推进成“正式应聘”。岗位直接沿用寻访记录，只供查看，原寻访记录也会保留。</p><label class="field">本次应聘岗位<div class="locked-job-reference" :class="{ empty: !convertingJob }"><template v-if="convertingJob"><b>{{ convertingJob.company || '未设置公司' }} · {{ convertingJob.name }}</b><small>岗位编号 {{ convertingJob.recruitmentCode || String(convertingJob.id).padStart(3, '0') }} · 已招 {{ convertingJob.hiredCount || 0 }}/{{ convertingJob.headcount || 1 }} · 系统自动带入</small></template><template v-else><b>寻访记录没有关联岗位</b><small>请先在寻访记录中补齐岗位。</small></template></div></label><label class="field spaced">HR<HrPicker v-model="convertOwner" :employees="hrs" placeholder="输入姓名模糊搜索 HR" /></label><div class="dialog-actions"><button class="btn" :disabled="busy" @click="converting = null">取消</button><button class="btn btn-primary" :disabled="busy || !convertingJob" @click="convert">{{ busy ? '创建中…' : '创建应聘经历' }}</button></div></el-dialog>
  <el-dialog :model-value="!!leaving" @update:model-value="value => { if (!value && !busy) leaving = null }" title="办理员工离职" width="510px"><p class="muted">离职只能在员工管理中办理，保存后会同步更新人才档案状态。</p><label class="field">离职日期 *<el-date-picker v-model="leaveForm.endDate" type="date" value-format="YYYY-MM-DD" format="YYYY/MM/DD" style="width:100%" /></label><label class="field spaced">离职原因 *<textarea v-model="leaveForm.reason" rows="4" maxlength="4000" placeholder="请写清离职原因，方便日后查询"></textarea></label><div class="dialog-actions"><button class="btn" :disabled="busy" @click="leaving = null">取消</button><button class="btn btn-primary" :disabled="busy" @click="saveLeave">{{ busy ? '保存中…' : '确认办理离职' }}</button></div></el-dialog>
  <el-dialog :model-value="!!hiring" @update:model-value="value => { if (!value && !busy) hiring = null }" title="办理入职" width="min(900px, 96vw)" top="4vh" class="hire-dialog" :close-on-click-modal="false"><p class="muted hire-intro">资料保存后会进入人才档案，并自动建立员工记录。</p><form class="hire-form" @submit.prevent="saveHire"><section><h3>01 · 用工类型</h3><div class="hire-options"><label v-for="option in ['全职','兼职','外包']" :key="option" :class="{ selected: hireForm.employmentCategory === option }"><input v-model="hireForm.employmentCategory" type="radio" :value="option" /><span>{{ option }}</span></label></div><div v-if="hireForm.employmentCategory === '全职'" class="hire-options sub-options"><label v-for="option in ['校招','社招']" :key="option" :class="{ selected: hireForm.hireChannel === option }"><input v-model="hireForm.hireChannel" type="radio" :value="option" /><span>{{ option }}</span></label></div><div v-if="hireForm.employmentCategory === '全职' && hireForm.hireChannel === '社招'" class="hire-options sub-options"><label v-for="option in ['在职','离职']" :key="option" :class="{ selected: hireForm.preEmploymentStatus === option }"><input v-model="hireForm.preEmploymentStatus" type="radio" :value="option" /><span>目前{{ option }}</span></label></div></section><section><h3>02 · 身份与联系</h3><div class="hire-grid"><label class="field">姓名 <span class="required">必填</span><input v-model.trim="hireForm.employeeName" maxlength="100" /></label><label class="field">电话 <span class="required">必填</span><input v-model.trim="hireForm.employeePhone" type="tel" maxlength="18" /></label><label class="field">邮箱 <span class="required">必填</span><input v-model.trim="hireForm.employeeEmail" type="email" maxlength="200" /></label><label class="field">身份证号 <span class="required">必填</span><input v-model.trim="hireForm.identityNumber" maxlength="18" /></label><label class="field">到岗日期 <span class="required">必填</span><el-date-picker v-model="hireForm.startDate" type="date" value-format="YYYY-MM-DD" format="YYYY/MM/DD" :disabled-date="disablePastDay" style="width:100%" /></label><label class="field">户籍地址 <span class="required">必填</span><input v-model.trim="hireForm.householdRegistration" maxlength="240" /></label><label class="field full-hire-field">现住址 <span class="required">必填</span><input v-model.trim="hireForm.address" maxlength="300" /></label></div></section><section><h3>03 · 银行与紧急联系</h3><div class="hire-grid"><label class="field">开户银行 <span class="required">必填</span><select v-model="hireForm.bankName"><option value="">请选择开户银行</option><option v-for="bank in banks" :key="bank" :value="bank">{{bank}}</option></select></label><label class="field">银行卡号 <span class="required">必填</span><input v-model.trim="hireForm.bankAccount" inputmode="numeric" maxlength="25" /></label><label class="field">紧急联系人 <span class="required">必填</span><input v-model.trim="hireForm.emergencyContact" maxlength="120" placeholder="姓名" /></label><label class="field">紧急联系电话 <span class="required">必填</span><input v-model.trim="hireForm.emergencyPhone" type="tel" maxlength="18" placeholder="11 位手机号" /></label></div></section><section><h3>04 · 入职材料</h3><div class="onboarding-file-grid"><label v-for="item in [{key:'identityFront',label:'身份证正面'},{key:'identityBack',label:'身份证反面'},...(hireForm.employmentCategory === '全职' && hireForm.hireChannel === '校招' ? [{key:'graduationCertificate',label:'毕业证'},{key:'degreeCertificate',label:'学位证'},{key:'educationVerification',label:'教育部学籍在线验证报告'}] : []),...(hireForm.employmentCategory === '全职' && hireForm.hireChannel === '社招' && hireForm.preEmploymentStatus === '离职' ? [{key:'departureCertificate',label:'离职证明'}] : [])]" :key="item.key" class="onboarding-file" :class="{ selected: hireFiles[item.key] }"><input type="file" accept=".pdf,.doc,.docx,.png,.jpg,.jpeg,.webp" @change="chooseHireFile(item.key, $event)" /><span>＋</span><b>{{ item.label }}</b><small>{{ hireFiles[item.key]?.name || (hireFileRequired(item.key) ? '必填 · 选择文件' : '选择文件') }}</small></label></div></section><p v-if="hireError" class="inline-error" role="alert">{{ hireError }}</p><div class="dialog-actions"><button type="button" class="btn" :disabled="busy" @click="hiring = null">取消</button><button class="btn btn-primary" :disabled="busy">{{ busy ? '正在并行上传并归档…' : '确认入职' }}</button></div></form></el-dialog>
  <el-dialog :model-value="!!interviewDetail" @update:model-value="value => { if (!value) interviewDetail = null }" title="面试详情" width="min(680px, 94vw)" destroy-on-close>
    <div v-if="interviewDetail" class="interview-detail"><header><span class="interview-avatar large"><img v-if="avatarUrls[interviewDetail.personId]" :src="avatarUrls[interviewDetail.personId]" :alt="interviewDetail.personName+'的证件照'" /><template v-else>{{ interviewDetail.personName?.slice(0, 1) || '人' }}</template></span><div><h2>{{ interviewDetail.personName }}</h2><p>本次面试安排</p></div><span class="badge" :class="interviewDetail.status === '已完成' ? 'green' : ''">{{ interviewDetail.status || '待面试' }}</span></header>
      <section class="interview-job-focus"><small>应聘岗位</small><h3>{{ interviewDetail.jobName || interviewDetailPosition?.name || '岗位待补充' }}</h3><p>{{ interviewDetail.company || interviewDetailPosition?.company || '未设置公司' }} · {{ interviewDetailPosition?.department || '部门待补充' }} · {{ interviewDetailPosition?.minSalary ?? '—' }} — {{ interviewDetailPosition?.maxSalary ?? '—' }} K / 月</p><div><span><b>岗位介绍</b>{{ interviewDetailPosition?.description || '暂无岗位介绍' }}</span><span><b>任职要求</b>{{ interviewDetailPosition?.requirements || '暂无任职要求' }}</span></div></section>
      <section class="interview-schedule-block"><small>面试安排</small><dl><div><dt>面试时间</dt><dd>{{ dateTime(interviewDetail.scheduledAt) }}</dd></div><div><dt>轮次</dt><dd>{{ interviewDetail.round || '待补充' }}</dd></div><div><dt>面试方式</dt><dd>{{ interviewDetail.method || '待补充' }}</dd></div><div><dt>面试官</dt><dd>{{ interviewDetail.owner || '待安排' }}</dd></div></dl></section>
      <section v-if="interviewDetail.status === '已完成'" class="interview-result-block"><small>面试结果</small><dl><div><dt>综合评分</dt><dd>{{ interviewDetail.score != null ? `${interviewDetail.score} 分` : '待补充' }}</dd></div><div><dt>推荐结论</dt><dd>{{ interviewDetail.result && interviewDetail.result !== '待评价' ? interviewDetail.result : '待补充' }}</dd></div></dl><p>{{ interviewDetail.feedback || '面试结果尚未补充评价依据。' }}</p></section>
      <section v-else class="interview-pending-note"><b>面试尚未完成</b><p>完成面试后再填写评分、结论和评价依据。</p></section><section v-if="interviewDetail.reason"><small>改期 / 取消 / 未出席原因</small><p>{{ interviewDetail.reason }}</p></section></div>
    <template #footer><div class="dialog-actions"><button class="btn" @click="interviewDetail = null">关闭</button><button v-if="interviewDetail" class="btn" @click="openInterviewEditor(interviewDetail, 'schedule')">修改安排</button><button v-if="interviewDetail" class="btn btn-primary" @click="openInterviewEditor(interviewDetail, 'evaluation')">结果</button></div></template>
  </el-dialog>
  <ApplicationDetailDialog :model-value="Boolean(applicationDetail)" :application="applicationDetail" :photo-url="avatarUrls[applicationDetail?.personId] || ''" :position="applicationDetailPosition" :communication-only="key === 'communications'" :events="data.communications || []" :interviews="data.interviews || []" :offers="data.offers || []" :employments="data.employments || []" @update:model-value="value => { if (!value) applicationDetail = null }" @record-communication="recordCommunication" @update-status="openTransitionFromDetail" @next-action="openApplicationNext" @edit-interview="editInterviewFromDetail" @edit-offer="editOfferFromDetail" />
