  <el-dialog :model-value="Boolean(roleCredentials)" @update:model-value="value => { if (!value) roleCredentials = null }" title="HR 登录账号已生成" width="520px"><p class="muted">账号和初始密码只在这里显示一次，请立即交给该 HR 保存。</p><dl v-if="roleCredentials" class="credential-card"><div><dt>登录账号</dt><dd>{{ roleCredentials.username }}</dd></div><div><dt>初始密码</dt><dd>{{ roleCredentials.initialPassword }}</dd></div></dl><template #footer><button class="btn btn-primary" @click="roleCredentials = null">我已记下</button></template></el-dialog>
